        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    womenVP: 12,
                    minorityVP: 2,
                    genderPayGap: 8.4,
                    racialPayGap: 6.1,
                    belongingScore: 6.4,
                    belongingGap: 2.7,
                    turnoverUR: 1.5,
                    execAlignment: 3.0,
                    totalSpent: 0,
                    auditDone: false,
                    auditQuality: 0,
                    ergModel: 'social',
                    representationHistory: [],
                    payGapHistory: [],
                    belongingHistory: [],
                    execAlignHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    hiringInvest: 50,
                    payEquityInvest: 50,
                    inclusionInvest: 50,
                    ergInvest: 25,
                    accountInvest: 25,
                    strategy: 'external_audit'
                };
            }
            this._setupSliderListeners();
            this._updateBriefing(state);
            if (!this.__langBound) {
                this.__langBound = true;
                var self = this;
                document.addEventListener('express:langchanged', function() {
                    try {
                        var st = (window.mySimulation && window.mySimulation.state) || state;
                        self._updateBriefing({ currentPeriod: st.currentPeriod }, true);
                    } catch (e) {}
                });
            }
        }

        _setupSliderListeners() {
            var sliders = ['hiringInput', 'payEquityInput', 'inclusionInput', 'ergInput', 'accountInput'];
            var valueIds = ['hiringValue', 'payEquityValue', 'inclusionValue', 'ergValue', 'accountValue'];
            var self = this;

            sliders.forEach(function(sliderId, i) {
                var slider = document.getElementById(sliderId);
                if (slider) {
                    slider.addEventListener('input', function() {
                        var valEl = document.getElementById(valueIds[i]);
                        if (valEl) valEl.textContent = slider.value;
                        self._updateBudgetTotal();
                    });
                }
            });
        }

        _updateBudgetTotal() {
            var h = parseInt(document.getElementById('hiringInput')?.value || 0);
            var p = parseInt(document.getElementById('payEquityInput')?.value || 0);
            var inc = parseInt(document.getElementById('inclusionInput')?.value || 0);
            var e = parseInt(document.getElementById('ergInput')?.value || 0);
            var a = parseInt(document.getElementById('accountInput')?.value || 0);
            var total = h + p + inc + e + a;
            var el = document.getElementById('totalAllocated');
            if (el) {
                el.textContent = '$' + total + 'K';
                el.style.color = total > 250 ? '#e74c3c' : '#27ae60';
            }
            var remEl = document.getElementById('budgetRemainingDisplay');
            if (remEl) {
                var rem = Math.max(0, 250 - total);
                remEl.textContent = '$' + rem + 'K';
                remEl.style.color = total > 250 ? '#e74c3c' : '#27ae60';
            }
        }

        _updateBriefing(state, repaintOnly) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            /* the runtime keeps the language in vcI18n; the framework instance has no language property */
            var lang = 'en';
            try {
                if (window.vcI18n && window.vcI18n._lang) { lang = window.vcI18n._lang; }
                else if (window.mySimulation && window.mySimulation.lang) { lang = window.mySimulation.lang; }
                else if (window.mySimulation && window.mySimulation.language) { lang = window.mySimulation.language; }
                else if (window.mySimulation && window.mySimulation.currentLanguage) { lang = window.mySimulation.currentLanguage; }
                else if (document.documentElement && document.documentElement.lang) { lang = document.documentElement.lang; }
            } catch (e) {}
            lang = String(lang).toLowerCase().slice(0, 2);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefing;
            }

            var selectEl = document.getElementById('strategySelect');
            if (selectEl && repaintOnly) {
                /* a language switch renames the options in place, so the choice already made stays selected */
                round.options.forEach(function(opt) {
                    for (var k = 0; k < selectEl.options.length; k++) {
                        if (selectEl.options[k].value === opt.value) { selectEl.options[k].textContent = lang === 'es' ? opt.labelEs : opt.label; }
                    }
                });
            } else if (selectEl) {
                selectEl.innerHTML = '';
                round.options.forEach(function(opt) {
                    var option = document.createElement('option');
                    option.value = opt.value;
                    option.textContent = lang === 'es' ? opt.labelEs : opt.label;
                    selectEl.appendChild(option);
                });
            }

            var tt = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            if (tt) {
                ['structuralChart', 'cultureChart'].forEach(function(cid) {
                    var cv = document.getElementById(cid);
                    if (cv) { cv.setAttribute('role', 'img'); cv.setAttribute('aria-label', tt(cid === 'structuralChart' ? 'chart_structural_alt' : 'chart_culture_alt')); }
                });
            }

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                if (round.event) {
                    eventPanel.style.display = 'block';
                    eventText.innerHTML = lang === 'es' ? round.event.textEs : round.event.text;
                } else {
                    eventPanel.style.display = 'none';
                }
            }
        }

        validateDecisions(decisions) {
            var hEl = document.getElementById('hiringInput');
            var pEl = document.getElementById('payEquityInput');
            var iEl = document.getElementById('inclusionInput');
            var eEl = document.getElementById('ergInput');
            var aEl = document.getElementById('accountInput');
            var sEl = document.getElementById('strategySelect');

            if (hEl) decisions.hiringInvest = parseInt(hEl.value);
            if (pEl) decisions.payEquityInvest = parseInt(pEl.value);
            if (iEl) decisions.inclusionInvest = parseInt(iEl.value);
            if (eEl) decisions.ergInvest = parseInt(eEl.value);
            if (aEl) decisions.accountInvest = parseInt(aEl.value);
            if (sEl) decisions.strategy = sEl.value;

            var total = decisions.hiringInvest + decisions.payEquityInvest + decisions.inclusionInvest + decisions.ergInvest + decisions.accountInvest;

            if (total > 250) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }
            if (total <= 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('zero_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var totalSpent = d.hiringInvest + d.payEquityInvest + d.inclusionInvest + d.ergInvest + d.accountInvest;

            var accountMultiplier = 1 + (d.accountInvest / 50) * 0.35;

            if (d.accountInvest >= 30) {
                ds.execAlignment = Math.min(10, ds.execAlignment + 0.45 * accountMultiplier);
            } else if (d.accountInvest >= 15) {
                ds.execAlignment = Math.min(10, ds.execAlignment + 0.2);
            } else {
                ds.execAlignment = Math.max(1, ds.execAlignment - 0.1);
            }

            /* stocks set by earlier quarters land now, before this quarter adds its own */
            this._drainStocks(ds);

            var strategyBonus = this._applyStrategy(d.strategy, ds, state.currentPeriod);

            var hiringEffect = (d.hiringInvest / 100) * 1.1 * accountMultiplier;
            ds.womenVP = Math.min(50, ds.womenVP + hiringEffect * 0.65 + strategyBonus.repBonus);
            ds.minorityVP = Math.min(30, ds.minorityVP + hiringEffect * 0.3 + strategyBonus.repBonus * 0.4);

            var payAuditMult = ds.auditDone ? (1 + ds.auditQuality * 0.3) : 0.4;
            var payEffect = (d.payEquityInvest / 100) * 0.9 * accountMultiplier * payAuditMult;
            ds.genderPayGap = Math.max(0, ds.genderPayGap - payEffect + strategyBonus.payBonus);
            ds.racialPayGap = Math.max(0, ds.racialPayGap - payEffect * 0.75);

            var belongInclusion = (d.inclusionInvest / 100) * 0.32;
            var belongStructural = ((d.hiringInvest + d.payEquityInvest) / 200) * 0.15 * accountMultiplier;
            var belongERG = (d.ergInvest / 50) * 0.12;
            ds.belongingScore = Math.min(10, ds.belongingScore + belongInclusion + belongStructural + belongERG + strategyBonus.belongBonus);

            var gapReduction = (belongStructural * 0.25 + belongERG * 0.12) * accountMultiplier;
            ds.belongingGap = Math.max(0, ds.belongingGap - gapReduction + strategyBonus.gapBonus);

            var turnoverReduction = ((d.payEquityInvest + d.hiringInvest) / 200) * 0.06 * accountMultiplier;
            turnoverReduction += belongERG * 0.025;
            ds.turnoverUR = Math.max(1.0, ds.turnoverUR - turnoverReduction);

            if (totalSpent > 0 && (d.inclusionInvest / totalSpent) > 0.55 && d.accountInvest < 15) {
                ds.belongingScore = Math.max(4, ds.belongingScore - 0.1);
                ds.execAlignment = Math.max(1, ds.execAlignment - 0.15);
            }

            if (round.event) {
                ds.belongingScore = Math.max(3, ds.belongingScore + (round.event.belongingHit || 0));
                ds.turnoverUR = Math.min(2.5, ds.turnoverUR + (round.event.turnoverHit || 0));
            }

            ds.totalSpent += totalSpent;
            if (!Array.isArray(ds.decisionLog)) { ds.decisionLog = []; }
            ds.decisionLog.push({ q: state.currentPeriod || ds.decisionLog.length + 1, s: d.strategy, h: d.hiringInvest, p: d.payEquityInvest, i: d.inclusionInvest, e: d.ergInvest, a: d.accountInvest });

            ds.representationHistory.push(Math.round(ds.womenVP * 10) / 10);
            ds.payGapHistory.push(Math.round(ds.genderPayGap * 10) / 10);
            ds.belongingHistory.push(Math.round(ds.belongingScore * 10) / 10);
            ds.execAlignHistory.push(Math.round(ds.execAlignment * 10) / 10);

            var results = {
                period: state.currentPeriod,
                totalSpent: totalSpent,
                womenVP: Math.round(ds.womenVP * 10) / 10,
                minorityVP: Math.round(ds.minorityVP * 10) / 10,
                genderPayGap: Math.round(ds.genderPayGap * 10) / 10,
                racialPayGap: Math.round(ds.racialPayGap * 10) / 10,
                belongingScore: Math.round(ds.belongingScore * 10) / 10,
                belongingGap: Math.round(ds.belongingGap * 10) / 10,
                turnoverUR: Math.round(ds.turnoverUR * 100) / 100,
                execAlignment: Math.round(ds.execAlignment * 10) / 10
            };

            // platform score: one banded formula for every round and for the final verdict (see _composite)
            var overallScore = this._composite(ds);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore, tier: this._tier(overallScore) });
            results.overallScore = overallScore;
            results.score = overallScore;

            var nextPeriod = (state.currentPeriod || 1) + 1;
            if (nextPeriod <= (state.maxPeriods || this.ROUNDS.length)) {
                this._updateBriefing({ currentPeriod: nextPeriod });
            }

            return results;
        }

        /* The one scoring function: five KPIs, each on two or three flat bands, 100 points in all.
           Reads the unrounded domainState, so the grade of every round and the final verdict agree. */
        _composite(m) {
            var s = 0;
            var num = function(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; };
            var wvp = num(m.womenVP, 12), gap = num(m.genderPayGap, 8.4), bel = num(m.belongingScore, 6.4);
            var tov = num(m.turnoverUR, 1.5), ex = num(m.execAlignment, 3);
            if (wvp >= 25) { s += 25; } else if (wvp >= 18) { s += 15; } else { s += 5; }
            if (gap <= 2) { s += 25; } else if (gap <= 5) { s += 15; } else { s += 5; }
            if (bel >= 8) { s += 20; } else if (bel >= 7) { s += 12; } else { s += 4; }
            if (tov <= 1.1) { s += 15; } else if (tov <= 1.25) { s += 10; } else { s += 3; }
            if (ex >= 7) { s += 15; } else if (ex >= 5) { s += 8; } else { s += 2; }
            return Math.max(0, Math.min(100, s));
        }

        /* ids of the decisions in this run that the teaching note and the case treat as mistakes, most costly first */
        _mistakesMade(log) {
            var out = [];
            if (!Array.isArray(log) || !log.length) return out;
            var byQ = function(q) { for (var k = 0; k < log.length; k++) { if (log[k] && log[k].q === q) return log[k]; } return log[q - 1] || null; };
            var n = function(v) { return typeof v === 'number' && isFinite(v) ? v : 0; };
            var q4 = byQ(4), q1 = byQ(1), q5 = byQ(5);
            if (q4 && q4.s === 'suppress') out.push('contained_leak');
            if (q1 && q1.s === 'no_audit') out.push('no_audit');
            var structure = 0, sentiment = 0, account = 0;
            log.forEach(function(r) { if (!r) return; structure += n(r.h) + n(r.p); sentiment += n(r.i) + n(r.e); account += n(r.a); });
            if (sentiment > structure) out.push('sentiment_trap');
            if (account / log.length < 15) out.push('no_accountability');
            if (q5 && q5.s === 'mandatory_training') out.push('mandatory_training');
            return out;
        }

        _tier(score) {
            if (score >= 80) return 'transformational';
            if (score >= 60) return 'strong_progress';
            if (score >= 40) return 'moderate_progress';
            return 'needs_improvement';
        }

        /* Delayed consequences carried in domainState (EQIL S3):
           trustDeficit - belonging points still to be lost after a contained pay-gap leak. The case reports that
             companies that contained or denied a leaked pay document lost 1.8 belonging points on average within a
             quarter; here the loss lands in the quarter after the response, with exits of under-represented staff.
           trainingBacklash - quarters of resistance left after mandatory bias training answered the manager backlash
             (Kalev, Dobbin and Kelly 2006; Dobbin and Kalev 2016: compulsory training is followed by resentment and by
             falls in managerial diversity). */
        _drainStocks(ds) {
            var deficit = typeof ds.trustDeficit === 'number' ? ds.trustDeficit : 0;
            if (deficit > 0) {
                ds.belongingScore = Math.max(3, ds.belongingScore - deficit);
                ds.belongingGap = Math.min(5, ds.belongingGap + deficit * 0.2);
                ds.turnoverUR = Math.min(2.5, ds.turnoverUR + 0.05);
                ds.trustDeficit = 0;
            }
            var backlash = typeof ds.trainingBacklash === 'number' ? ds.trainingBacklash : 0;
            if (backlash > 0) {
                ds.belongingScore = Math.max(3, ds.belongingScore - 0.15);
                ds.belongingGap = Math.min(5, ds.belongingGap + 0.1);
                ds.womenVP = Math.max(5, ds.womenVP - 0.3);
                ds.minorityVP = Math.max(0, ds.minorityVP - 0.1);
                ds.execAlignment = Math.max(1, ds.execAlignment - 0.25);
                ds.turnoverUR = Math.min(2.5, ds.turnoverUR + 0.02);
                ds.trainingBacklash = backlash - 1;
            }
        }

        _applyStrategy(strategy, ds, period) {
            var bonus = { repBonus: 0, payBonus: 0, belongBonus: 0, gapBonus: 0 };

            switch (strategy) {
                case 'external_audit':
                    ds.auditDone = true;
                    ds.auditQuality = 1.0;
                    bonus.payBonus = -0.3;
                    break;
                case 'internal_audit':
                    ds.auditDone = true;
                    ds.auditQuality = 0.5;
                    bonus.payBonus = -0.15;
                    break;
                case 'no_audit':
                    break;
                case 'structured_hiring':
                    bonus.repBonus = 0.6;
                    break;
                case 'skills_assessment':
                    bonus.repBonus = 0.8;
                    break;
                case 'diverse_panels':
                    bonus.repBonus = 0.4;
                    bonus.belongBonus = 0.1;
                    break;
                case 'erg_social':
                    ds.ergModel = 'social';
                    bonus.belongBonus = 0.15;
                    break;
                case 'erg_talent':
                    ds.ergModel = 'talent';
                    bonus.repBonus = 0.3;
                    bonus.belongBonus = 0.1;
                    break;
                case 'erg_business':
                    ds.ergModel = 'business';
                    bonus.repBonus = 0.2;
                    bonus.belongBonus = 0.15;
                    bonus.gapBonus = -0.08;
                    break;
                case 'full_transparency':
                    bonus.belongBonus = 0.3;
                    bonus.gapBonus = -0.15;
                    ds.execAlignment = Math.min(10, ds.execAlignment + 0.5);
                    break;
                case 'internal_only':
                    bonus.belongBonus = 0.1;
                    break;
                case 'suppress':
                    /* the quarter looks calm; the trust loss lands next quarter (see _drainStocks) */
                    ds.trustDeficit = (typeof ds.trustDeficit === 'number' ? ds.trustDeficit : 0) + 1.8;
                    ds.execAlignment = Math.max(1, ds.execAlignment - 0.3);
                    break;
                case 'mandatory_training':
                    bonus.belongBonus = 0.05;
                    bonus.repBonus = -0.1;
                    ds.trainingBacklash = 3;
                    break;
                case 'voluntary_allyship':
                    bonus.belongBonus = 0.2;
                    bonus.gapBonus = -0.1;
                    break;
                case 'inclusive_leadership':
                    bonus.belongBonus = 0.15;
                    bonus.repBonus = 0.25;
                    ds.execAlignment = Math.min(10, ds.execAlignment + 0.3);
                    break;
                case 'cdo_ceo':
                    ds.execAlignment = Math.min(10, ds.execAlignment + 0.8);
                    bonus.repBonus = 0.3;
                    break;
                case 'cdo_hr':
                    ds.execAlignment = Math.min(10, ds.execAlignment + 0.3);
                    break;
                case 'distributed':
                    ds.execAlignment = Math.min(10, ds.execAlignment + 0.6);
                    bonus.repBonus = 0.15;
                    bonus.belongBonus = 0.1;
                    break;
                case 'timebound_targets':
                    bonus.repBonus = 0.5;
                    ds.execAlignment = Math.min(10, ds.execAlignment + 0.4);
                    break;
                case 'progress_goals':
                    bonus.repBonus = 0.35;
                    bonus.belongBonus = 0.1;
                    break;
                case 'aspirational':
                    bonus.repBonus = 0.1;
                    break;
                case 'public_report':
                    bonus.belongBonus = 0.25;
                    ds.execAlignment = Math.min(10, ds.execAlignment + 0.5);
                    bonus.gapBonus = -0.12;
                    break;
                case 'internal_report':
                    bonus.belongBonus = 0.1;
                    break;
                case 'bonus_tied':
                    ds.execAlignment = Math.min(10, ds.execAlignment + 0.7);
                    bonus.repBonus = 0.4;
                    bonus.payBonus = -0.2;
                    break;
            }
            return bonus;
        }

