                            title: { display: true, text: window.mySimulation.t('chart_culture_title') }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 10, title: { display: true, text: window.mySimulation.t('chart_score_axis') } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.representationHistory.map(function(_, i) { return 'Q' + (i + 1); });
            return {
                structuralChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.representationHistory },
                        { data: state.domainState.payGapHistory }
                    ]
                },
                cultureChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.belongingHistory },
                        { data: state.domainState.execAlignHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            /* a zero pay gap is a real value: read every KPI with a type check, never with a falsy fallback */
            var num = function(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; };
            var womenVP = num(r.womenVP, 12);
            var payGap = num(r.genderPayGap, 8.4);
            var belonging = num(r.belongingScore, 6.4);
            var turnover = num(r.turnoverUR, 1.5);
            var execAlign = num(r.execAlignment, 3);

            /* the grade is the score the platform stored for the last quarter; recomputed only when it is missing */
            var lastPerf = last.domainState && last.domainState.performance;
            var score = (lastPerf && typeof lastPerf.overallScore === 'number') ? lastPerf.overallScore
                : (typeof r.overallScore === 'number' ? r.overallScore
                : this._composite({ womenVP: womenVP, genderPayGap: payGap, belongingScore: belonging, turnoverUR: turnover, execAlignment: execAlign }));
            var tier = this._tier(score);
            var performance = window.mySimulation.t('perf_' + tier);

            var totalSpent = history.reduce(function(s, h) { return s + (h.results?.totalSpent || 0); }, 0);

            /* name the mistakes this run actually made, from its own decisions; the first one found is the turning point */
            var log = (last.domainState && Array.isArray(last.domainState.decisionLog)) ? last.domainState.decisionLog
                : history.map(function(h, k) { var dd = h.decisions || {}; return { q: k + 1, s: dd.strategy, h: dd.hiringInvest, p: dd.payEquityInvest, i: dd.inclusionInvest, e: dd.ergInvest, a: dd.accountInvest }; });
            var made = this._mistakesMade(log);
            var tFn = window.mySimulation.t.bind(window.mySimulation);
            var insights = made.map(function(id, k) {
                var line = tFn('mistake_' + id);
                return k === 0 ? tFn('turning_point') + ': ' + line : line;
            });
            if (payGap <= 2) insights.push(window.mySimulation.t('insight_pay_gap_eliminated'));
            if (payGap > 5) insights.push(window.mySimulation.t('insight_pay_gap_significant'));
            if (womenVP >= 25) insights.push(window.mySimulation.t('insight_representation_improved'));
            if (womenVP < 18) insights.push(window.mySimulation.t('insight_representation_limited'));
            if (belonging >= 8 && payGap > 5) insights.push(window.mySimulation.t('insight_dei_trap'));
            if (execAlign >= 7) insights.push(window.mySimulation.t('insight_exec_alignment_strong'));
            if (execAlign < 5) insights.push(window.mySimulation.t('insight_exec_alignment_weak'));

            return {
                totalBudgetUsed: '$' + totalSpent + 'K',
                finalWomenVP: womenVP + '%',
                finalPayGap: payGap + '%',
                finalBelonging: belonging + '/10',
                finalTurnover: turnover + 'x',
                finalExecAlignment: execAlign + '/10',
                overallScore: score,
                totalScore: score,
                score: score,
                composite: score,
                performance: performance,
                performanceLabel: performance,
                performanceTier: tier,
                insights: insights
            };
        }

        /* Debrief card: score and verdict, the final KPI strip, what drove the result (turning point first),
           and two questions for the class. Every string comes from the translation table. */
        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = window.mySimulation.t.bind(window.mySimulation);
            var score = typeof summary.overallScore === 'number' ? summary.overallScore : 0;
            var kpi = function(label, value) {
                return '<div class="dei-cm-kpi"><div class="dei-cm-kpi-label">' + t(label) + '</div><div class="dei-cm-kpi-value">' + (value == null ? '' : value) + '</div></div>';
            };
            var items = (Array.isArray(summary.insights) ? summary.insights : []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="dei-cm" role="status">' +
                '<div class="dei-cm-score"><span class="dei-cm-num">' + score + '</span><span class="dei-cm-of">/100</span></div>' +
                '<div class="dei-cm-tier">' + (summary.performanceLabel || summary.performance || '') + '</div>' +
                '<div class="dei-cm-kpis">' +
                    kpi('women_vp_label', summary.finalWomenVP) + kpi('pay_gap_label', summary.finalPayGap) +
                    kpi('belonging_label', summary.finalBelonging) + kpi('turnover_label', summary.finalTurnover) +
                    kpi('exec_align_label', summary.finalExecAlignment) +
                '</div>' +
                (items ? '<h4 class="dei-cm-h">' + t('debrief_insights') + '</h4><ul class="dei-cm-list">' + items + '</ul>' : '') +
                '<h4 class="dei-cm-h">' + t('debrief_questions') + '</h4><ol class="dei-cm-list">' +
                    '<li>' + t('debrief_q1') + '</li><li>' + t('debrief_q2') + '</li>' +
                '</ol></div>';
        }

        getHint(state, results) {
            if (!results) return null;

            if (results.genderPayGap > 6 && state.currentPeriod >= 3) {
                return window.mySimulation.t('hint_pay_gap');
            }
            if (results.belongingScore > 7.5 && results.womenVP < 15) {
                return window.mySimulation.t('hint_sentiment_trap');
            }
            if (results.execAlignment < 4 && state.currentPeriod >= 4) {
                return window.mySimulation.t('hint_exec_alignment');
            }
            if (results.turnoverUR > 1.4 && state.currentPeriod >= 5) {
                return window.mySimulation.t('hint_turnover');
            }
            if (state.currentPeriod <= 2 && !state.domainState.auditDone) {
                return window.mySimulation.t('hint_audit');
            }
            return null;
        }

